// Authored NOT_RUN. No topology/FL equivalence assertion.
use kni_core::closed_fit::{prepare_closed,ClosureAlias,RingFitInput,AssemblyBoundary};
use kni_core::cubic_fit::FitPolicy;
use kni_core::decision_evidence_envelope::PinClaim;
use kni_core::fitter_requirements::SourceFitRun;
use kni_core::reference_slice::Point;
fn pin()->PinClaim{PinClaim{algorithm:"fixture".into(),claimed_digest:"NOT_VERIFIED".into(),subject_ref:"ring".into()}}
fn ring()->RingFitInput{let p=vec![Point{x:0.,y:0.},Point{x:1.,y:0.},Point{x:0.,y:1.},Point{x:0.,y:0.}];RingFitInput{runs:vec![SourceFitRun{source_pin:pin(),frame_pin:pin(),ring_index:0,span_indices:vec![0,1,2,3],points:p,start_tangent:Point{x:1.,y:0.},end_tangent:Point{x:0.,y:1.},tangent_binding:pin(),seam_binding:pin()}],closure_alias:ClosureAlias{final_source_index:3,first_source_index:0,binding:pin()}}}
#[test]fn closure_alias_not_inferred(){let mut input=ring();input.closure_alias.final_source_index=99;let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.closed_candidate.is_none());assert!(out.boundaries.contains(&AssemblyBoundary::ClosureAliasMismatch));}
#[test]fn exact_geometry_closure_required(){let mut input=ring();input.runs[0].points[3].x=0.01;let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.closed_candidate.is_none());assert!(out.boundaries.contains(&AssemblyBoundary::ClosureMismatch));}
#[test]fn invalid_threshold_precedes_base_case(){let out=prepare_closed(ring(),&FitPolicy{squared_error:f64::NAN,max_refits:0});assert!(out.pieces.is_empty());assert!(out.boundaries.contains(&AssemblyBoundary::InvalidPolicy));}
#[test]fn initial_two_point_not_child_base_case(){let mut input=ring();input.runs[0].points.truncate(2);input.runs[0].span_indices.truncate(2);let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.pieces.is_empty());assert!(out.boundaries.iter().any(|x|matches!(x,AssemblyBoundary::UnresolvedChild{..})));}
fn triangle()->RingFitInput{let vertices=[Point{x:0.,y:0.},Point{x:2.,y:0.},Point{x:0.,y:2.},Point{x:0.,y:0.}];let mut runs=Vec::new();for i in 0..3{let a=vertices[i];let b=vertices[i+1];let points=vec![a,Point{x:(a.x+b.x)/2.,y:(a.y+b.y)/2.},b];runs.push(SourceFitRun{source_pin:pin(),frame_pin:pin(),ring_index:0,span_indices:vec![2*i,2*i+1,2*i+2],points,start_tangent:Point{x:b.x-a.x,y:b.y-a.y},end_tangent:Point{x:a.x-b.x,y:a.y-b.y},tangent_binding:pin(),seam_binding:pin()});}RingFitInput{runs,closure_alias:ClosureAlias{final_source_index:6,first_source_index:0,binding:pin()}}}
#[test]fn singular_spans_split_into_closed_cubic_children(){let out=prepare_closed(triangle(),&FitPolicy{squared_error:0.,max_refits:0});assert!(out.boundaries.is_empty());let ring=out.closed_candidate.unwrap();assert_eq!(out.pieces.len(),6);assert_eq!(ring.spans.len(),6);assert_eq!(out.pieces[0].controls[0],out.pieces.last().unwrap().controls[3]);for pair in out.pieces.windows(2){assert_eq!(pair[0].controls[3],pair[1].controls[0]);}}
#[test]fn sibling_piece_preserved_but_no_partial_ring(){let mut input=triangle();input.runs[1].points[1].x=f64::NAN;let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.closed_candidate.is_none());assert_eq!(out.pieces.len(),4);assert!(out.pieces.iter().all(|p|p.run_index!=1));assert!(out.boundaries.contains(&AssemblyBoundary::InvalidRun{run:1}));}
#[test]fn source_frame_ring_mismatch_never_closes(){for field in 0..3{let mut input=triangle();match field{0=>input.runs[1].source_pin.claimed_digest="different".into(),1=>input.runs[1].frame_pin.subject_ref="different".into(),_=>input.runs[1].ring_index=1};let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.boundaries.contains(&AssemblyBoundary::BindingMismatch{run:1}));assert!(out.closed_candidate.is_none());}}
#[test]fn one_index_per_sample_required(){let mut input=triangle();input.runs[1].span_indices.pop();let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.boundaries.contains(&AssemblyBoundary::InvalidRun{run:1}));assert!(out.closed_candidate.is_none());}
#[test]fn nonwrap_source_join_mismatch_rejects(){let mut input=triangle();input.runs[1].span_indices[0]=99;let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.boundaries.contains(&AssemblyBoundary::SourceJoinMismatch{run:1}));assert!(out.closed_candidate.is_none());}
#[test]fn nonwrap_geometry_join_mismatch_rejects(){let mut input=triangle();input.runs[1].points[0].x=99.;let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.boundaries.contains(&AssemblyBoundary::JoinMismatch{run:1}));assert!(out.closed_candidate.is_none());}
#[test]fn repeated_endpoint_chord_unresolved_siblings_continue(){let mut input=triangle();input.runs[1].points[1]=input.runs[1].points[0];let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.boundaries.iter().any(|b|matches!(b,AssemblyBoundary::UnresolvedChild{run:1,..})));assert_eq!(out.pieces.len(),4);assert!(out.closed_candidate.is_none());}
#[test]fn zero_chord_span_never_manufactures_handles(){let mut input=triangle();let a=input.runs[1].points[0];input.runs[1].points=vec![a,a,a];let out=prepare_closed(input,&FitPolicy{squared_error:0.,max_refits:0});assert!(out.boundaries.iter().any(|b|matches!(b,AssemblyBoundary::UnresolvedChild{run:1,..})));assert!(out.pieces.iter().all(|p|p.run_index!=1));assert!(out.closed_candidate.is_none());}
